import React, { useState } from "react";

// ─── STATUS BADGE ─────────────────────────────────────────────────────────────
function StatusBadge({ status }) {
  const configs = {
    SCHEDULED:  { label: "PROG.",      classes: "bg-slate-700 text-slate-400 border-slate-600" },
    TIMED:      { label: "PROG.",      classes: "bg-slate-700 text-slate-400 border-slate-600" },
    LIVE:       { label: "EN VIVO",    classes: "bg-red-500/20 text-red-400 border-red-500/40" },
    IN_PLAY:    { label: "EN VIVO",    classes: "bg-red-500/20 text-red-400 border-red-500/40" },
    PAUSED:     { label: "HT",         classes: "bg-amber-500/20 text-amber-400 border-amber-500/40" },
    FINISHED:   { label: "FIN",        classes: "bg-slate-800 text-slate-500 border-slate-700" },
    POSTPONED:  { label: "POSPUESTO", classes: "bg-orange-500/20 text-orange-400 border-orange-500/40" },
  };
  const config = configs[status] || configs.SCHEDULED;
  return (
    <span className={`inline-flex items-center px-2 py-0.5 rounded border text-xs font-bold tracking-widest ${config.classes}`}>
      {config.label}
    </span>
  );
}

// ─── MATCH TIME ───────────────────────────────────────────────────────────────
function MatchTime({ utcDate }) {
  if (!utcDate) return <span className="text-slate-600">--:--</span>;
  const date = new Date(utcDate);
  return (
    <span className="number-display text-slate-400 text-sm">
      {date.toLocaleTimeString("es-ES", { hour: "2-digit", minute: "2-digit" })}
    </span>
  );
}

// ─── MINI OUTCOME BAR ─────────────────────────────────────────────────────────
function MiniOutcomeBar({ home, draw, away }) {
  if (!home && !draw && !away) return null;
  return (
    <div className="flex rounded-full overflow-hidden h-1.5 w-full mt-2 gap-0.5">
      <div className="bg-blue-500 rounded-l-full"   style={{ width: `${home}%` }} title={`Local ${home}%`} />
      <div className="bg-slate-500"                  style={{ width: `${draw}%` }} title={`Empate ${draw}%`} />
      <div className="bg-purple-500 rounded-r-full"  style={{ width: `${away}%` }} title={`Visitante ${away}%`} />
    </div>
  );
}

// ─── HELPERS ──────────────────────────────────────────────────────────────────
function getTeamName(team) {
  if (!team) return "Desconocido";
  if (typeof team === "string") return team;
  if (typeof team === "object") return team.name || team.nombre || "Desconocido";
  return String(team);
}

function getCompetitionName(match) {
  return (
    match.competición?.nombre ||
    match.competition?.name   ||
    match.competicion?.nombre ||
    match.league?.name        ||
    "Competición"
  );
}

function getMonteCarloPct(match) {
  const mc = match.monteCarlo;
  if (!mc) return { home: null, draw: null, away: null };
  return {
    home:  mc["Victoria local"]       ?? mc.homeWin ?? null,
    draw:  mc["empate"]               ?? mc.draw    ?? null,
    away:  mc["victoria visitante"]   ?? mc.awayWin ?? null,
  };
}

function getScore(match) {
  const ft = match.score?.fullTime;
  if (!ft) return null;
  if (ft.home === null || ft.home === undefined) return null;
  if (ft.away === null || ft.away === undefined) return null;
  return { home: ft.home, away: ft.away };
}

// ─── PANEL DE SUGERENCIA ──────────────────────────────────────────────────────
function SuggestionPanel({ match, onClose }) {
  const homeName  = getTeamName(match.homeTeam);
  const awayName  = getTeamName(match.awayTeam);
  const { home: homeWin, draw, away: awayWin } = getMonteCarloPct(match);

  const golesLocal   = match.expectedGoals?.local     ?? match.expectedGoals?.home ?? null;
  const golesVisita  = match.expectedGoals?.visitante ?? match.expectedGoals?.away ?? null;
  const totalXG      = golesLocal && golesVisita
    ? (parseFloat(golesLocal) + parseFloat(golesVisita)).toFixed(2)
    : null;

  const pronoScore = match.mostLikelyScore;
  const pronoIA    = match.pronosticoIA;

  // ── Lógica de sugerencia automática ─────────────────────────────────────────
  function buildSuggestion() {
    const lines = [];

    // 1X2
    if (homeWin !== null && draw !== null && awayWin !== null) {
      const h = Number(homeWin);
      const d = Number(draw);
      const a = Number(awayWin);
      const max = Math.max(h, d, a);

      if (max === h && h >= 55) {
        lines.push({
          mercado: "Victoria directa",
          apuesta: `1 — ${homeName}`,
          razon: `El modelo le da ${h.toFixed(1)}% de probabilidad. Clara ventaja local.`,
          nivel: "alta",
        });
      } else if (max === a && a >= 50) {
        lines.push({
          mercado: "Victoria directa",
          apuesta: `2 — ${awayName}`,
          razon: `Visitante favorito con ${a.toFixed(1)}% según Monte Carlo.`,
          nivel: "alta",
        });
      } else if (d >= 28) {
        lines.push({
          mercado: "Doble oportunidad",
          apuesta: `1X — ${homeName} o Empate`,
          razon: `Partido igualado. Empate en ${d.toFixed(1)}%, conviene cubrirse.`,
          nivel: "media",
        });
      } else {
        lines.push({
          mercado: "Hándicap Asiático",
          apuesta: `${h > a ? homeName : awayName} -0.5`,
          razon: "Diferencia estadística pequeña; el hándicap ofrece mejor valor.",
          nivel: "media",
        });
      }
    }

    // Goles
    if (totalXG !== null) {
      const xg = parseFloat(totalXG);
      if (xg >= 2.7) {
        lines.push({
          mercado: "Goles Over/Under",
          apuesta: "Over 2.5 goles",
          razon: `xG combinado de ${totalXG}. El modelo anticipa un partido con goles.`,
          nivel: "alta",
        });
      } else if (xg <= 1.8) {
        lines.push({
          mercado: "Goles Over/Under",
          apuesta: "Under 2.5 goles",
          razon: `xG combinado de ${totalXG}. Partido cerrado, pocos goles esperados.`,
          nivel: "alta",
        });
      } else {
        lines.push({
          mercado: "Goles Over/Under",
          apuesta: "Over 1.5 goles",
          razon: `xG de ${totalXG}. Línea de 1.5 más segura que la de 2.5.`,
          nivel: "media",
        });
      }
    }

    // BTTS
    const bttsY = match.monteCarlo?.["ambos anotan"] ??
                  match.monteCarlo?.bttsYes           ?? null;
    if (bttsY !== null && Number(bttsY) >= 55) {
      lines.push({
        mercado: "Ambos Anotan (BTTS)",
        apuesta: "Sí",
        razon: `${Number(bttsY).toFixed(1)}% de probabilidad de que ambos equipos marquen.`,
        nivel: "media",
      });
    }

    return lines;
  }

  const suggestions = buildSuggestion();

  const nivelColor = {
    alta:  "text-emerald-400 border-emerald-500/40 bg-emerald-500/10",
    media: "text-amber-400 border-amber-500/40 bg-amber-500/10",
    baja:  "text-slate-400 border-slate-600 bg-slate-800/40",
  };

  return (
    <div
      className="mt-3 rounded-xl border border-slate-700/60 overflow-hidden animate-fade-in"
      style={{ background: "linear-gradient(135deg, #0f1f14 0%, #0c1220 100%)" }}
    >
      {/* Header del panel */}
      <div className="flex items-center justify-between px-4 py-2.5 border-b border-slate-700/40">
        <div className="flex items-center gap-2">
          <span className="text-base">🎯</span>
          <span className="text-emerald-400 text-xs font-bold tracking-widest display-font">
            SUGERENCIAS DE APUESTA
          </span>
        </div>
        <button
          onClick={(e) => { e.stopPropagation(); onClose(); }}
          className="text-slate-600 hover:text-slate-400 transition-colors text-lg leading-none"
        >
          ×
        </button>
      </div>

      {/* Marcador Poisson */}
      {pronoScore && (
        <div className="px-4 pt-3 pb-1 flex items-center gap-2">
          <span className="text-slate-600 text-xs">Resultado más probable:</span>
          <span className="number-display text-emerald-400 text-sm font-bold">
            {typeof pronoScore === "string" ? pronoScore : "–"}
          </span>
          <span className="text-slate-600 text-xs">(Poisson)</span>
        </div>
      )}

      {/* Cards de sugerencia */}
      <div className="px-4 py-3 space-y-2">
        {suggestions.length === 0 ? (
          <p className="text-slate-600 text-xs">
            Datos insuficientes para generar sugerencias automáticas.
          </p>
        ) : (
          suggestions.map((s, i) => (
            <div
              key={i}
              className={`rounded-lg border px-3 py-2.5 ${nivelColor[s.nivel] || nivelColor.baja}`}
            >
              <div className="flex items-center justify-between mb-1">
                <span className="text-xs font-bold tracking-wide">{s.mercado}</span>
                <span className="text-xs opacity-70 uppercase tracking-widest">
                  {s.nivel === "alta" ? "⭐ Alta conf." : "⚡ Media conf."}
                </span>
              </div>
              <div className="text-white text-sm font-semibold mb-0.5">{s.apuesta}</div>
              <div className="text-xs opacity-70 leading-relaxed">{s.razon}</div>
            </div>
          ))
        )}
      </div>

      {/* Pronóstico IA (resumen) */}
      {pronoIA && typeof pronoIA === "string" && (
        <div className="px-4 pb-4 pt-1 border-t border-slate-800/60 mt-1">
          <div className="flex items-center gap-1.5 mb-2">
            <span className="text-xs">🤖</span>
            <span className="text-slate-500 text-xs font-semibold tracking-widest">
              ANÁLISIS IA
            </span>
          </div>
          <p className="text-slate-400 text-xs leading-relaxed line-clamp-4">
            {pronoIA}
          </p>
        </div>
      )}
    </div>
  );
}

// ─── SINGLE MATCH CARD ────────────────────────────────────────────────────────
function MatchCard({ match, onAnalyze }) {
  const [showSuggestion, setShowSuggestion] = useState(false);

  const isFinished = match.status === "FINISHED";
  const isLive     = match.status === "IN_PLAY" || match.status === "LIVE" || match.status === "PAUSED";

  const homeTeamName    = getTeamName(match.homeTeam);
  const awayTeamName    = getTeamName(match.awayTeam);
  const competitionName = getCompetitionName(match);
  const { home: homeWin, draw, away: awayWin } = getMonteCarloPct(match);
  const score = getScore(match);

  return (
    <div
      className="match-card rounded-xl p-4 animate-fade-in cursor-pointer"
      onClick={() => onAnalyze(match)}
    >
      {/* Top row */}
      <div className="flex items-center justify-between mb-3">
        <span
          className="text-slate-600 text-xs truncate max-w-[140px]"
          title={competitionName}
        >
          {competitionName}
        </span>
        <div className="flex items-center gap-2 shrink-0">
          <MatchTime utcDate={match.utcDate} />
          <StatusBadge status={match.status} />
        </div>
      </div>

      {/* Teams + Score */}
      <div className="flex items-center gap-3">
        <div className="flex-1 text-right">
          <span className="display-font text-base text-white leading-tight">
            {homeTeamName}
          </span>
        </div>

        <div className="flex flex-col items-center gap-0.5 w-16 shrink-0">
          {isFinished && score ? (
            <span className="number-display text-xl font-bold text-white">
              {score.home} – {score.away}
            </span>
          ) : isLive && score ? (
            <span className="number-display text-xl font-bold text-red-400">
              {score.home} – {score.away}
            </span>
          ) : match.mostLikelyScore ? (
            <div className="text-center">
              <span className="text-emerald-500 number-display text-xs font-semibold">
                {typeof match.mostLikelyScore === "string" ? match.mostLikelyScore : "–"}
              </span>
              <div className="text-slate-600 text-xs">PRONO</div>
            </div>
          ) : (
            <span className="text-slate-600 text-sm">vs</span>
          )}
        </div>

        <div className="flex-1">
          <span className="display-font text-base text-white leading-tight">
            {awayTeamName}
          </span>
        </div>
      </div>

      {/* Mini bar */}
      {homeWin !== null && draw !== null && awayWin !== null && (
        <MiniOutcomeBar
          home={Number(homeWin)}
          draw={Number(draw)}
          away={Number(awayWin)}
        />
      )}

      {/* Bottom row */}
      <div className="flex items-center justify-between mt-3">
        {homeWin !== null && draw !== null && awayWin !== null ? (
          <div className="flex items-center gap-3 text-xs text-slate-600">
            <span>1 <span className="text-blue-400 number-display">{Number(homeWin).toFixed(1)}%</span></span>
            <span>X <span className="text-slate-400 number-display">{Number(draw).toFixed(1)}%</span></span>
            <span>2 <span className="text-purple-400 number-display">{Number(awayWin).toFixed(1)}%</span></span>
          </div>
        ) : (
          <div />
        )}

        <div className="flex items-center gap-2">
          {/* Botón Sugerencias */}
          <button
            onClick={(e) => {
              e.stopPropagation();
              setShowSuggestion((prev) => !prev);
            }}
            className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold border transition-all duration-150 ${
              showSuggestion
                ? "bg-emerald-500/20 text-emerald-300 border-emerald-500/50"
                : "text-amber-400 border-amber-500/30 hover:bg-amber-500/10 hover:border-amber-500/60"
            }`}
          >
            🎯 {showSuggestion ? "Ocultar" : "Sugerencias"}
          </button>

          {/* Botón Analizar (solo partidos programados) */}
          {(match.status === "SCHEDULED" || match.status === "TIMED") && (
            <button
              onClick={(e) => {
                e.stopPropagation();
                onAnalyze(match);
              }}
              className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold text-emerald-400 border border-emerald-500/30 hover:bg-emerald-500/10 hover:border-emerald-500/60 transition-all duration-150"
            >
              <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" />
              </svg>
              Analizar
            </button>
          )}
        </div>
      </div>

      {/* Panel de sugerencias expandible */}
      {showSuggestion && (
        <SuggestionPanel
          match={match}
          onClose={() => setShowSuggestion(false)}
        />
      )}
    </div>
  );
}

// ─── SKELETON ─────────────────────────────────────────────────────────────────
function MatchListSkeleton() {
  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
      {Array.from({ length: 9 }).map((_, i) => (
        <div key={i} className="rounded-xl p-4 h-36 shimmer-bg" />
      ))}
    </div>
  );
}

// ─── MAIN EXPORT ──────────────────────────────────────────────────────────────
export default function MatchList({ matches, loading, onAnalyze }) {
  const [filter, setFilter] = useState("ALL");
  const [search, setSearch] = useState("");

  const filters = [
    { id: "ALL",       label: "Todos"       },
    { id: "SCHEDULED", label: "Programados" },
    { id: "LIVE",      label: "En Vivo"     },
    { id: "FINISHED",  label: "Finalizados" },
  ];

  if (loading) {
    return (
      <section>
        <div className="flex items-center gap-4 mb-5">
          <div className="h-6 w-36 rounded shimmer-bg" />
          <div className="ml-auto h-8 w-48 rounded-lg shimmer-bg" />
        </div>
        <MatchListSkeleton />
      </section>
    );
  }

  if (!matches || matches.length === 0) {
    return (
      <section>
        <div className="text-center py-20 text-slate-600">
          <svg className="w-12 h-12 mx-auto mb-4 opacity-30" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" />
          </svg>
          <p className="display-font text-xl">Sin partidos para esta fecha</p>
          <p className="text-sm mt-1">Prueba con otra fecha del calendario</p>
        </div>
      </section>
    );
  }

  const filtered = matches.filter((m) => {
    const statusMatch =
      filter === "ALL" ||
      m.status === filter ||
      (filter === "LIVE" && (m.status === "IN_PLAY" || m.status === "LIVE" || m.status === "PAUSED"));

    const homeName = getTeamName(m.homeTeam).toLowerCase();
    const awayName = getTeamName(m.awayTeam).toLowerCase();
    const compName = getCompetitionName(m).toLowerCase();
    const q = search.toLowerCase();

    const searchMatch = !search || homeName.includes(q) || awayName.includes(q) || compName.includes(q);

    return statusMatch && searchMatch;
  });

  return (
    <section>
      {/* Header */}
      <div className="flex flex-wrap items-center gap-3 mb-5">
        <div className="flex items-center gap-2">
          <svg className="w-4 h-4 text-slate-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 10h16M4 14h16M4 18h16" />
          </svg>
          <h2 className="display-font text-xl text-white tracking-wide">CARTELERA DEL DÍA</h2>
          <span className="number-display text-slate-500 text-sm">({matches.length})</span>
        </div>

        <div className="ml-auto relative">
          <svg className="w-3.5 h-3.5 text-slate-600 absolute left-2.5 top-1/2 -translate-y-1/2" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
          </svg>
          <input
            type="text"
            placeholder="Buscar equipo o liga..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="pl-8 pr-3 py-1.5 bg-slate-800/60 border border-slate-700 rounded-lg text-sm text-slate-300 placeholder-slate-600 focus:outline-none focus:border-emerald-500/50 w-52"
          />
        </div>
      </div>

      {/* Filter pills */}
      <div className="flex items-center gap-2 mb-5 flex-wrap">
        {filters.map((f) => (
          <button
            key={f.id}
            onClick={() => setFilter(f.id)}
            className={`px-3 py-1.5 rounded-lg text-xs font-semibold border transition-all duration-150 ${
              filter === f.id
                ? "bg-emerald-500/20 text-emerald-400 border-emerald-500/40"
                : "bg-slate-800/40 text-slate-500 border-slate-700 hover:text-slate-300"
            }`}
          >
            {f.label}
          </button>
        ))}
      </div>

      {/* Grid */}
      {filtered.length === 0 ? (
        <div className="text-center py-10 text-slate-600 text-sm">
          No hay partidos que coincidan con el filtro
        </div>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3 stagger-children">
          {filtered.map((match, idx) => (
            <MatchCard
              key={match.id || match.matchId || idx}
              match={match}
              onAnalyze={onAnalyze}
            />
          ))}
        </div>
      )}
    </section>
  );
}
